    fun getTodaySentenceEntry(): DailySentenceEntry {
        val calendar = Calendar.getInstance()
        val dayOfYear = calendar.get(Calendar.DAY_OF_YEAR)
        val index = (dayOfYear - 1) % sentences100Days.size
        return sentences100Days[index]
    }

    fun getSentenceByDay(day: Int): DailySentenceEntry {
        val clamped = (day - 1).coerceIn(0, sentences100Days.size - 1)
        return sentences100Days[clamped]
    }
}
